// A scenario has its own result. Source references are kept beside the staff instructions.
export const BILLING_ACCEPTANCE_REVISION = "mts-hospital-billing-v2";

type BillingCase = readonly [
  id: string, title: string, webmed: string, fixture: string,
  steps: readonly string[], expected: string, evidence: string, conditional?: true,
];

function group(
  title: string, role: string, path: string, cases: readonly BillingCase[],
): AcceptanceGroup {
  return {
    title, role,
    cases: cases.map(([id, label, webmed, fixture, steps, expected, evidence, conditional]): AcceptanceCase => [
      id, label, webmed, steps.join(" "), expected, conditional, { fixture, steps, evidence, path },
    ]),
  };
}

